export function Form(props, registry, hydrate) {
    const { children, onSubmit, onError, onSuccess, action, method = 'POST', class: className, style, ...rest } = props;
    if (formIsSSR()) {
        const attrs = { action: actionUrl(action), method, novalidate: true };
        if (className)
            attrs.class = className;
        if (style)
            attrs.style = style;
        for (const [k, v] of Object.entries(rest)) {
            if (v != null && v !== false)
                attrs[k] = v;
        }
        const attrStr = Object.entries(attrs)
            .filter(([, v]) => v != null && v !== false)
            .map(([k, v]) => v === true ? k : `${k}="${String(v).replace(/"/g, '&quot;')}"`)
            .join(' ');
        return `<form ${attrStr}>${children || ''}</form>`;
    }
    if (hydrate && hydrate.nextElement) {
        let form = hydrate.nextElement('form');
        if (form && !form.parentNode && hydrate.root) {
            const existing = hydrate.root.querySelector('form');
            if (existing)
                form = existing;
        }
        if (form) {
            form.noValidate = true;
            bindFormSubmit(form, { action, method, onSubmit, onError, onSuccess });
        }
        return document.createDocumentFragment();
    }
    const form = document.createElement('form');
    const resolvedAction = actionUrl(action);
    if (resolvedAction)
        form.action = resolvedAction;
    if (method)
        form.method = method;
    form.noValidate = true;
    if (className)
        form.className = className;
    if (style)
        form.style.cssText = style;
    for (const [k, v] of Object.entries(rest)) {
        if (typeof v === 'string')
            form.setAttribute(k, v);
    }
    if (children)
        appendChildren(form, children);
    bindFormSubmit(form, { action, method, onSubmit, onError, onSuccess });
    return form;
}
